mapper.select:
SELECT nnum, ntitle, nwriter, NCONTENT, nhit, ndate, membernum, row_num FROM (SELECT nnum, ntitle, nwriter, NCONTENT, nhit, ndate, membernum, ROW_NUMBER() OVER(ORDER BY nnum desc) AS row_num FROM notice
nwriter like '%' || #{searchValue} || '%'
ntitle like '%' || #{searchValue} || '%'
ncontent like '%' || #{searchValue} || '%'
) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}

mapper.update:
UPDATE notice
SET
    ntitle = #{ntitle},
    nwriter = #{nwriter},
    ncontent = #{ncontent}
WHERE nnum = #{nnum}
